 state.edges.forEach((e,i)=>{if(e.kind==='route')return;let a=port(get(e.from),e.item,true,lane(e,'from'),at(e,'from'),0,e.fromSlot),b=port(get(e.to),e.item,false,lane(e,'to'),at(e,'to'),0,e.toSlot),d=curve(a,b);html+=`<path class="transfer-hit" data-edge="${i}" d="${d}"/><path class="transfer ${result.rates[i]<.01?'dry':''} ${selectedEdge===i?'selected-link':''} ${fluids.has(e.item)?'fluid-link':''}" data-edge="${i}" d="${d}"/><text class="transfer-label ${selectedEdge===i||selected===e.from||selected===e.to?'connection-detail':''}" data-live-rate="${i}" x="${(a.x+b.x)/2+6}" y="${(a.y+b.y)/2}">${fluids.has(e.item)?'PIPE ·':''} ${glyph(e.item)} ${fmt(result.rates[i])}${fluids.has(e.item)?' units/min':'/m'}</text>${!window.factoryItemMode&&fluids.has(e.item)&&result.rates[i]>.01?`<path class="pipe-flow" d="${d}"/>`:''}${!fluids.has(e.item)?tokens(d,e.item,result.rates[i],Math.max(150,result.rates[i]),Math.max(1,Math.hypot(b.x-a.x,b.y-a.y))):''}`});
