function stoppedFlowIssues(){const stopped=state.nodes.filter(n=>n.kind==='machine'&&result.stats[n.id]?.actual<.00001),problems=[];const add=(id,text,edge=null)=>problems.push({id,text,edge});for(const n of stopped){for(const item of Object.keys(E.inputs(n)))if(!state.edges.some(e=>e.to===n.id&&e.item===item))add(n.id,`${label(sourceItem(n))} needs a ${label(item)} connection.`);if(!n.terminal&&!state.edges.some(e=>e.from===n.id))add(n.id,`${label(sourceItem(n))} has nowhere to send its output.`);}for(const n of state.nodes){if(n.kind==='source'&&!(n.supply>0))add(n.id,`${label(n.item)} supply is set to zero.`);if(n.kind==='belt'&&!n.full&&!state.edges.some(e=>e.to===n.id))add(n.id,`${n.name||n.id} has nothing feeding it.`);}state.edges.forEach((e,i)=>{if(e.limit===0)add(e.to,`${label(e.item)} transfer is capped at zero.`,i)});return {stopped,problems}}
