function bindNetwork(){document.querySelectorAll('#network [data-select]').forEach(el=>activate(el,ev=>{ev.stopPropagation();select(el.dataset.select)}));document.querySelectorAll('[data-edge],[data-route]').forEach(el=>el.onclick=ev=>{ev.stopPropagation();selectedEdge=+(el.dataset.edge??el.dataset.route);selected=null;pending=null;drawNetwork();inspect();openDetails();$('sidebar').scrollTop=0});document.querySelectorAll('[data-tap]').forEach(el=>activate(el,ev=>{ev.stopPropagation();let n=get(el.dataset.tap),l=+el.dataset.lane,i=+el.dataset.at;if(pending&&pending.id!==n.id){finish(n.id,n.lanes[l],{toLane:l,toAt:i});return}if(!n.lanes[l]){select(n.id);openDetails();message('Assign a material to this lane first.');return}pending={id:n.id,fromLane:l,fromAt:i};drawNetwork();message(`Selected ${n.name}, lane ${l?'B':'A'}. Click a matching ingredient socket.`)}));document.querySelectorAll('[data-bend]').forEach(el=>{el.onpointerdown=ev=>{ev.preventDefault();ev.stopPropagation();remember();let n=get(el.dataset.bend),i=+el.dataset.at;drag={id:n.id,at:i,x:ev.clientX,y:ev.clientY,ox:n.points[i].x,oy:n.points[i].y,whole:ev.shiftKey,original:n.points.map(p=>({...p}))}};el.onkeydown=ev=>{const d={ArrowLeft:[-40,0],ArrowRight:[40,0],ArrowUp:[0,-40],ArrowDown:[0,40]}[ev.key];if(!d)return;ev.preventDefault();remember();let n=get(el.dataset.bend),p=n.points[+el.dataset.at];p.x=Math.max(40,Math.min(6000,p.x+d[0]));p.y=Math.max(80,Math.min(6000,p.y+d[1]));commit('Belt bend moved.');document.querySelector(`[data-bend="${n.id}"][data-at="${el.dataset.at}"]`)?.focus()}})}
function bindCards(){document.querySelectorAll('[data-move-belt]').forEach(el=>el.onpointerdown=ev=>{if(ev.button!==0)return;ev.preventDefault();ev.stopPropagation();const n=get(el.dataset.moveBelt);remember();selected=n.id;selectedEdge=null;drag={id:n.id,whole:true,at:0,x:ev.clientX,y:ev.clientY,ox:n.points[0].x,oy:n.points[0].y,original:n.points.map(p=>({...p}))};});document.querySelectorAll('#cards [data-select]').forEach(el=>el.onclick=()=>{select(el.dataset.select);openDetails()});document.querySelectorAll('[data-drag]').forEach(el=>{el.onpointerdown=ev=>{if(ev.button!==0)return;ev.preventDefault();ev.stopPropagation();remember();let n=get(el.dataset.drag);selected=n.id;selectedEdge=null;drag={id:n.id,x:ev.clientX,y:ev.clientY,ox:n.x,oy:n.y}};activate(el,()=>{select(el.dataset.drag);openDetails()})});document.querySelectorAll('[data-out]').forEach(el=>el.onclick=ev=>{ev.stopPropagation();pending={id:el.dataset.out,item:el.dataset.outputItem||sourceItem(get(el.dataset.out)),...(el.dataset.canvasSlot!==undefined?{fromSlot:+el.dataset.canvasSlot}:{})};drawNetwork();message('Choose a matching belt lane to load it, or another machine’s ingredient for direct transfer.')});document.querySelectorAll('[data-in]').forEach(el=>el.onclick=ev=>{ev.stopPropagation();if(pending)finish(el.dataset.in,el.dataset.item,el.dataset.canvasSlot!==undefined?{toSlot:+el.dataset.canvasSlot}:{});else{select(el.dataset.in);openDetails();message('Choose a supply lane or machine output first.')}})}
function finish(to,item,extra={}){if(!pending)return;if(pending.item&&pending.item!==item){message('Choose an input for '+label(pending.item)+'.');return;}const a=get(pending.id),b=get(to);if(a.kind==='belt'&&b.kind==='belt'){message('Use Join another route in the belt details to connect continuous conveyors.');return}let e=transfer(a,b,item,{...pending,...extra});delete e.id;let err=error(e);if(err){message(err);return}if(state.edges.length>=100){message('Maximum 100 links.');return}remember();state.edges.push(e);let shared=false;if(a.kind==='machine'&&b.kind==='belt'){const loaders=state.edges.filter(x=>x.from===a.id&&x.to===b.id&&x.item===item&&x.kind==='transfer');if([0,1].every(l=>loaders.some(x=>lane(x,'to')===l))){loaders.forEach(x=>x.autoLaneSharing=true);shared=true;}}if(a.kind==='machine')a.terminal=false;selected=b.id;commit(shared?'Both lane connections are active. Available output is shared across A and B.':fluids.has(item)?'Fluid link added. Rate follows supply and recipe demand; physical pipe capacity is not simulated.':'Transfer added at 120/min. Select its line to compare direct insertion and belts.');}
const opts=(list,val)=>list.map(k=>`<option value="${k}" ${k===val?'selected':''}>${esc(label(k))}</option>`).join('');
function editNumber(id,fn,min=0,max=100000,integer=false){$(id).onchange=ev=>{let v=+ev.target.value;if(!Number.isFinite(v)||v<min||v>max||integer&&!Number.isInteger(v)){message(`Enter ${integer?'a whole number':'a number'} from ${min} to ${max}.`);inspect();return}remember();fn(v);commit()}}
function removeNode(){const n=get(selected);if(!n)return;remember();state.nodes=state.nodes.filter(x=>x!==n);state.edges=state.edges.filter(e=>e.from!==n.id&&e.to!==n.id);selected=state.nodes[0]?.id;commit('Removed. Undo restores it.')}
function removeEdge(i){remember();const e=state.edges[i];state.edges=state.edges.filter((x,j)=>e.kind==='route'?!(x.kind==='route'&&x.from===e.from&&x.to===e.to):j!==i);commit('Connection removed. Check the downstream route for lost supply.')}
function inspect(){$('deleteSelection').disabled=selectedEdge===null&&!get(selected);if(selectedEdge!==null){inspectEdge();return}const n=get(selected);if(!n){$('inspector').innerHTML='<h2>Your factory, as routes</h2><p>Draw a belt, assign its two lanes, and split it into named branches. Connect machines where they pick up ingredients.</p>'+trackingHTML();bindTracking();return}if(n.kind==='belt')inspectBelt(n);else if(n.kind==='splitter')inspectSplitter(n);else if(n.kind==='machine')inspectMachine(n);else inspectSource(n)}
function trackingHTML(){return `<h3>Track production</h3><label>PRODUCT<select id="track">${opts(Object.keys(RECIPES).sort(),state.product)}</select></label>`}
function bindTracking(){if($('track'))$('track').onchange=ev=>{remember();state.product=ev.target.value;commit()}}
function busFlowHTML(n){const cap=result.laneCap(n);return `<section class="bus-flow"><h3>Follow the material</h3><p>Moving items show lane flow. Each pickup leaves less material for machines downstream.</p>${[0,1].filter(l=>n.lanes[l]).map(l=>{const stages=result.belts[n.id][l];let before=n.full?cap:0;return `<h4 style="color:${color(n.lanes[l])}">Lane ${l?'B':'A'} · ${esc(label(n.lanes[l]))}</h4><div class="bus-flow-step"><b>Enters</b><span>${fmt(before)}/min</span></div>`+stages.map((st,i)=>{const incoming=before+st.loaded;before=st.remaining;const links=state.edges.map((e,k)=>({e,k})).filter(({e})=>e.from===n.id&&lane(e,'from')===l&&at(e,'from')===i);if(!links.length&&!st.loaded)return '';return `<div class="bus-flow-stop"><small>Pickup ${i+1} · ${fmt(incoming)}/min arriving</small>${st.loaded?`<div>+ ${fmt(st.loaded)}/min loaded</div>`:''}${links.map(({e,k})=>{const dest=get(e.to);return `<button class="full" data-link="${k}">↳ ${esc(dest.kind==='machine'?label(sourceItem(dest))+' · '+dest.id:dest.name||dest.id)} <b>−${fmt(result.rates[k])}/min</b></button>`}).join('')}<div class="bus-flow-step"><b>${fmt(st.remaining)}/min continues</b><span>${fmt(st.remaining/cap*100)}% full</span></div><div class="bus-density" style="--material:${color(n.lanes[l])};--spacing:${st.remaining>0?Math.min(160,12*cap/st.remaining):160}px;opacity:${st.remaining>0?1:.2}">${st.remaining>0?'<i></i>':''}</div></div>`}).join('')}).join('')}<small>Steady-state flow preview; item positions are illustrative.</small></section>`}
function inspectBelt(n){let cap=result.laneCap(n),incoming=state.edges.filter(e=>e.kind==='route'&&e.to===n.id),outgoing=state.edges.filter(e=>e.kind==='route'&&e.from===n.id),pickups=state.edges.filter(e=>e.from===n.id&&e.kind==='transfer');$('inspector').innerHTML=`<div class="eyebrow">BELT ROUTE · ${n.id.toUpperCase()}</div><h2>${esc(n.name||'Unnamed route')}</h2><label>ROUTE NAME / PURPOSE<input id="routeName" maxlength="70" value="${esc(n.name||'')}"></label><label>BELT TYPE<select id="tier">${['yellow','red','blue'].map(t=>`<option value="${t}" ${t===n.tier?'selected':''}>${label(t)} · ${{yellow:450,red:900,blue:1350}[t]}/min per lane</option>`).join('')}</select></label><label class="inline"><input type="checkbox" id="full" ${n.full?'checked':''} ${incoming.length?'disabled':''}>Full external supply at the start</label><p>${incoming.length?'Fed by '+[...new Set(incoming.map(e=>get(e.from).name||e.from))].map(esc).join(', '):n.full?'Both assigned lanes enter full.':'Empty until a machine or connected route fills it.'}</p>${[0,1].map(l=>`<label>LANE ${l?'B':'A'} MATERIAL<select id="lane${l}"><option value="">Empty lane</option>${opts(solids,n.lanes[l])}</select></label>`).join('')}<button id="splitHere" class="primary full">⑂ Split this into two routes</button><p>Marker spacing and frequency match calculated flow at steady state. At low rates, a belt can look empty between items. A stopped machine does not prove its belt is packed.</p><p>Solid items move along both lanes on this belt. Empty lanes indicate no material is arriving; internal belts must be fed by production.</p><label class="inline"><input id="beltEndBlocked" type="checkbox" ${n.endBlocked?'checked':''}>End stops here · no output leaves this belt</label><p>A closed end limits production to what machines pick up along the route. A packed end shows the settled queue when opening it would release more material.</p><label class="inline"><input id="exportEnd" type="checkbox" ${n.exportEnd?'checked':''}>Live items: remove at end (external consumer)</label><p>Leave this off for a physical belt end. Items stop and queue. Enable only to represent material being removed outside this layout.</p><h3>Where this route goes</h3>${outgoing.length?[...new Set(outgoing.map(e=>e.to))].map(k=>`<button class="full" data-focus="${k}">→ ${esc(get(k).name||k)}</button>`).join(''):(n.endBlocked?'<p>The end is closed. Material must be picked up along this route.</p>':'<p>The end continues out of this plan.</p>')}${pickups.map(e=>`<button class="full" data-link="${state.edges.indexOf(e)}">${glyph(e.item)} ${esc(label(e.item))} → ${e.to.toUpperCase()} · ${fmt(result.rates[state.edges.indexOf(e)])}/m</button>`).join('')}${busFlowHTML(n)}<h3>Visible lane balance</h3>${[0,1].map(l=>{let st=result.belts[n.id][l],sup=n.full&&n.lanes[l]?Math.max(0,st[0].remaining-st[0].loaded+st[0].taken):0,loaded=st.reduce((s,p)=>s+p.loaded,0),used=st.reduce((s,p)=>s+p.taken,0);return `<div class="connection"><b style="color:${color(n.lanes[l])}">${l?'B':'A'} · ${esc(label(n.lanes[l]))}</b><div class="row"><span>Enters / loaded</span><b>${fmt(sup+loaded)}/m</b></div><div class="row"><span>Taken / routed onward</span><b>${fmt(used)}/m</b></div><div class="row"><span>Remaining at end</span><b>${fmt(st.at(-1).remaining)}/m</b></div><div class="gauge"><i style="width:${st.at(-1).remaining/cap*100}%"></i></div></div>`}).join('')}<h3>Shape & pickup points</h3><p>Drag square handles. Shift-drag moves the whole route. Coordinates below offer precise placement.</p>${n.points.map((p,i)=>`<div class="point-row"><span>${i+1}</span><input type="number" aria-label="Point ${i+1} X" data-coord="x" data-index="${i}" value="${p.x}" min="40" max="6000"><input type="number" aria-label="Point ${i+1} Y" data-coord="y" data-index="${i}" value="${p.y}" min="80" max="6000"><button data-remove-point="${i}" aria-label="Remove point ${i+1}" ${n.points.length<=2?'disabled':''}>×</button></div>`).join('')}<button id="extend" class="full">＋ Extend route</button><h3>Join another route</h3><p>Connect this end to the start of a matching empty route. Both lanes must match.</p><select id="joinTarget"><option value="">Choose destination…</option>${state.nodes.filter(b=>b.kind==='belt'&&b!==n&&!b.full&&b.lanes.every((v,i)=>v===n.lanes[i])).map(b=>`<option value="${b.id}">${esc(b.name)} · ${b.id}</option>`).join('')}</select><button id="join" class="full">Join routes</button><button id="delete" class="full danger">Delete route</button>`;
 beltBalanceControls(n);$('exportEnd').onchange=ev=>{remember();n.exportEnd=ev.target.checked;commit('External consumer updated. Live items restart after a layout change.')};$('beltEndBlocked').onchange=ev=>{remember();n.endBlocked=ev.target.checked;commit('Belt end updated. Production and lane flow recalculated.')};$('routeName').onchange=ev=>{remember();n.name=ev.target.value.slice(0,70);commit()};$('tier').onchange=ev=>{const tier=ev.target.value;ev.target.value=n.tier;openTransportPreview('belt',n,{tier})};$('full').onchange=ev=>{remember();n.full=ev.target.checked;commit()};for(let l=0;l<2;l++)$('lane'+l).onchange=ev=>{remember();n.lanes[l]=ev.target.value;state.edges=state.edges.filter(e=>!(e.from===n.id&&lane(e,'from')===l||e.to===n.id&&lane(e,'to')===l));commit('Lane changed. Its old connections were removed; reconnect matching materials.')};$('splitHere').onclick=()=>splitRoute(n);$('delete').onclick=removeNode;$('extend').onclick=()=>{if(n.points.length>=20)return;remember();const old=n.points.length-1,p=n.points.at(-1);n.points.push({x:Math.min(6000,p.x+240),y:p.y});state.edges.forEach(e=>{if(e.from===n.id&&e.kind==='route')e.fromAt=old+1});commit('Route extended. Drag its end to add a bend.');fit()};document.querySelectorAll('[data-coord]').forEach(el=>el.onchange=ev=>{let v=+ev.target.value,key=el.dataset.coord;if(!Number.isFinite(v)||v<(key==='x'?40:80)||v>6000)return;remember();n.points[+el.dataset.index][key]=v;commit()});document.querySelectorAll('[data-remove-point]').forEach(el=>el.onclick=()=>{let i=+el.dataset.removePoint;if(n.points.length<=2)return;remember();n.points.splice(i,1);state.edges=state.edges.filter(e=>!(e.kind==='transfer'&&(e.from===n.id&&at(e,'from')===i||e.to===n.id&&at(e,'to')===i)));for(const e of state.edges){if(e.from===n.id){e.fromAt=e.kind==='route'?n.points.length-1:Math.max(0,at(e,'from')-(at(e,'from')>i?1:0))}if(e.to===n.id)e.toAt=e.kind==='route'?0:Math.max(0,at(e,'to')-(at(e,'to')>i?1:0))}commit()});$('join').onclick=()=>joinRoutes(n,get($('joinTarget').value));bindLinks()}
function bindLinks(){document.querySelectorAll('[data-focus]').forEach(el=>el.onclick=()=>select(el.dataset.focus));document.querySelectorAll('[data-link]').forEach(el=>el.onclick=()=>{selectedEdge=+el.dataset.link;selected=null;inspect()})}
function joinRoutes(a,b){if(!b){message('Choose a destination route.');return}let edges=[0,1].filter(l=>a.lanes[l]).map(l=>routeEdge(a,b,l,a.points.length-1,0)),temp={...state,edges:[...state.edges]};for(const e of edges){let err=error(e,temp);if(err){message(err);return}temp.edges.push(e)}if(temp.edges.length>100)return;remember();state.edges=temp.edges;commit('Routes joined. Material now travels from one belt to the next.')}
function splitRoute(n){if(!n||n.kind!=='belt'){message('Select a belt route first.');return}if(state.nodes.length>37||state.edges.length>94){message('Not enough room for this branch (40 nodes / 100 links maximum).');return}if(state.edges.some(e=>e.from===n.id&&e.kind==='route')){message('This route already feeds a connection. Select its downstream route to split again.');return}if(n.points.at(-1).x>5000){message('Move this route left to make room for branches.');return}remember();let p=n.points.at(-1),s={id:id(),kind:'splitter',name:(n.name||'Belt')+' split',x:p.x+130,y:p.y,tier:n.tier,lanes:[...n.lanes],policy:'balanced'},a=belt('BRANCH A · name this route',[{x:p.x+330,y:Math.max(100,p.y-200)},{x:p.x+650,y:Math.max(100,p.y-200)}],[...n.lanes],false,n.tier),b=belt('BRANCH B · name this route',[{x:p.x+330,y:Math.min(5800,p.y+200)},{x:p.x+650,y:Math.min(5800,p.y+200)}],[...n.lanes],false,n.tier);state.nodes.push(s,a,b);for(let l=0;l<2;l++)if(n.lanes[l])state.edges.push(routeEdge(n,s,l,n.points.length-1),routeEdge(s,a,l,0,0,0),routeEdge(s,b,l,0,0,1));selected=s.id;commit('Splitter added with two connected routes. Name each branch for what it will supply.');fit();openDetails()}
function inspectSplitter(n){const branches=[0,1].map(branch=>({branch,edges:state.edges.filter(e=>e.from===n.id&&e.branch===branch)})),total=state.edges.reduce((s,e,i)=>s+(e.to===n.id?result.rates[i]:0),0);$('inspector').innerHTML=`<div class="eyebrow">SPLITTER · ${n.id.toUpperCase()}</div><h2>Follow the split</h2><p>Two lanes in, two lanes on each branch. Lane A stays lane A; lane B stays lane B.</p><label>NAME<input id="splitName" maxlength="70" value="${esc(n.name)}"></label><label>OUTPUT DISTRIBUTION<select id="policy"><option value="balanced" ${n.policy==='balanced'?'selected':''}>Balanced · prefer 50 / 50</option><option value="a" ${n.policy==='a'?'selected':''}>Priority to branch A</option><option value="b" ${n.policy==='b'?'selected':''}>Priority to branch B</option></select></label><label>SPLITTER TYPE<select id="splitTier">${opts(['yellow','red','blue'],n.tier)}</select></label><div class="explain"><strong>${fmt(total)}/min arriving</strong><br>Balanced output divides each lane evenly when both branches have room. Priority fills the chosen branch first; excess goes to the other branch.</div>${branches.map(({branch,edges})=>{let flow=edges.reduce((sum,e)=>sum+result.rates[state.edges.indexOf(e)],0),dest=[...new Set(edges.map(e=>e.to))];return `<h3>BRANCH ${branch?'B':'A'} · ${fmt(flow)}/min</h3><div class="gauge"><i style="width:${total?flow/total*100:0}%"></i></div>${dest.map(k=>`<button class="full" data-focus="${k}">${esc(get(k).name||k)} →</button>`).join('')||'<p>No route connected.</p>'}${edges.map(e=>`<div class="row"><span>Lane ${lane(e,'from')?'B':'A'} · ${esc(label(e.item))}</span><b>${fmt(result.rates[state.edges.indexOf(e)])}/m</b></div>`).join('')}`}).join('')}<p>Open route ends carry unused supply onward. To model a blocked branch, lower its receiving belt capacity or remove that route connection.</p><button id="delete" class="full danger">Delete splitter</button>`;$('splitName').onchange=ev=>{remember();n.name=ev.target.value.slice(0,70);commit()};$('policy').onchange=ev=>{remember();n.policy=ev.target.value;commit('Splitter distribution updated. Follow the item markers into each branch.')};$('splitTier').onchange=ev=>{remember();n.tier=ev.target.value;commit()};$('delete').onclick=removeNode;bindLinks()}
function transferChoices(n){const choices=[];for(const a of state.nodes){if(a===n||a.kind==='splitter')continue;if(a.kind==='belt')a.lanes.forEach((item,l)=>{if(item in E.inputs(n))a.points.forEach((p,i)=>choices.push({from:a.id,to:n.id,item,fromLane:l,fromAt:i,text:`IN · ${a.name} / ${l?'B':'A'} / tap ${i+1}`}));if(item in E.outputs(n))a.points.forEach((p,i)=>choices.push({from:n.id,to:a.id,item,toLane:l,toAt:i,text:`OUT · ${a.name} / ${l?'B':'A'} / tap ${i+1}`}))});else{if(sourceItem(a) in E.inputs(n))choices.push({from:a.id,to:n.id,item:sourceItem(a),text:`IN · direct from ${a.id} / ${label(sourceItem(a))}`});if(a.kind==='machine'&&sourceItem(n) in E.inputs(a))choices.push({from:n.id,to:a.id,item:sourceItem(n),text:`OUT · direct to ${a.id} / ${label(sourceItem(a))}`})}}return choices}
function inspectMachine(n){const s=result.stats[n.id],r=RECIPES[n.recipe],choices=transferChoices(n),links=state.edges.filter(e=>e.from===n.id||e.to===n.id);$('inspector').innerHTML=`<div class="eyebrow">MACHINE · ${n.id.toUpperCase()}</div><h2>${esc(r.name)}</h2>${machineBuildSummary(n)}<section class="machine-settings"><h3>Machine setup</h3><label>Produces<select id="recipe">${opts(Object.keys(RECIPES).sort(),n.recipe)}</select></label><div class="two"><label>MACHINE<select id="machine">${E.options(n.recipe).map(k=>`<option value="${k}" ${k===n.machine?'selected':''}>${E.machines[k].label}</option>`).join('')}</select></label><label>COUNT<input id="count" type="number" min="1" max="10000" value="${n.count}"></label></div></section><details><summary>Ingredient supply &amp; calculations</summary><div class="explain"><strong>${fmt(s.actual)} / ${fmt(s.capacity)} per min</strong><br>${fmt(s.util)}% utilization. One ${E.machines[n.machine].label.toLowerCase()} produces ${fmt(E.per(n))}/min: ${r.out} per cycle ÷ ${fmt(r.time/E.speed(n))} seconds × 60.</div><h3>Ingredient supply</h3>${Object.entries(s.inputs).map(([item,v])=>`<div class="connection"><b style="color:${color(item)}">${glyph(item)} ${esc(label(item))}</b><div>${fmt(v.received)} received / ${fmt(v.need)} needed per min</div><div class="gauge"><i style="width:${v.percent}%"></i></div><small>${fmt(v.percent)}% of full-speed demand</small></div>`).join('')}${machineBeltBudget(n)}<p>Received means material consumed at the current production rate. A blocked output can also reduce input consumption.</p></details><h3>Output destination</h3><label class="inline"><input type="checkbox" id="terminal" ${n.terminal?'checked':''}>Accept extra output into storage</label><p>${n.terminal?fmt(s.delivered)+'/min enters storage / finished output.':'Production must fit through the connected output routes.'}</p><button id="outputRoute" class="full primary">＋ Make a dedicated output belt</button><details class="inspector-extra"><summary>Add a connection using a list</summary>${choices.length?`<select id="choice">${choices.map(c=>`<option value="${encodeURIComponent(JSON.stringify(c))}">${esc(c.text)}</option>`).join('')}</select><button id="connect" class="full">Connect this route</button>`:'<p>Add a matching supply lane or another machine to see connection choices.</p>'}</details><h3>Current transfers</h3>${links.map(e=>`<button class="full" data-link="${state.edges.indexOf(e)}">${e.from===n.id?'OUT':'IN'} · ${esc(label(e.item))} · ${fmt(result.rates[state.edges.indexOf(e)])}/min</button>`).join('')||'<p>No transfers connected yet.</p>'}<details><summary>Logical connections</summary><p>These are flowchart connection IDs, not physical positions. Use the individual assembler placement editor for three positions per side.</p><div class="slot-grid">${slots.map((s,i)=>{const e=links.find(e=>e.from===n.id&&e.fromSlot===i||e.to===n.id&&e.toSlot===i);return `<button ${e?`data-link="${state.edges.indexOf(e)}"`:'disabled'}>Connection ${i+1}<small>${e?(e.from===n.id?'OUT':'IN'):'Free'}</small></button>`}).join('')}</div></details><details><summary>Tracking &amp; research</summary>${trackingHTML()}<p>${r.tech?'Recipe research: '+esc(r.tech):'Recipe available from the start.'}</p></details><button id="delete" class="full danger">Delete machine</button>`;
 bindMachineGuidance(n);$('recipe').onchange=ev=>{remember();n.recipe=ev.target.value;delete n.outputSinks;delete n.plannedRate;n.machine=E.options(n.recipe)[0];state.edges=state.edges.filter(e=>e.from!==n.id&&e.to!==n.id);commit('Recipe changed. Old transfers removed; reconnect the new materials.')};$('machine').onchange=ev=>{remember();n.machine=ev.target.value;commit()};editNumber('count',v=>n.count=v,1,10000,true);$('terminal').onchange=ev=>{remember();n.terminal=ev.target.checked;commit()};$('delete').onclick=removeNode;$('outputRoute').onclick=()=>makeOutput(n);if($('connect'))$('connect').onclick=()=>{let c=JSON.parse(decodeURIComponent($('choice').value));pending={id:c.from,...(c.fromLane!==undefined?{fromLane:c.fromLane,fromAt:c.fromAt}:{})};finish(c.to,c.item,c.toLane!==undefined?{toLane:c.toLane,toAt:c.toAt}:{})};bindTracking();bindLinks();if((r.outputs||n.outputSinks!==undefined)&&typeof multiOutputControls==='function')multiOutputControls(n)}
function makeOutput(n){if(state.nodes.length>=40||state.edges.length>=100)return;if(RECIPES[n.recipe].fluidOut){message('Fluid output needs a pipe connection. Connect directly to a receiving chemical plant.');return}const slot=freeSlot(n);if(slot<0){message('No free attachment positions remain.');return}remember();const b=belt(label(sourceItem(n)).toUpperCase()+' → OUTPUT',[{x:Math.min(5500,n.x+330),y:Math.min(5600,n.y+220)},{x:Math.min(5900,n.x+650),y:Math.min(5600,n.y+220)}],[sourceItem(n),''],false);state.nodes.push(b);state.edges.push({from:n.id,to:b.id,item:sourceItem(n),kind:'transfer',toLane:0,toAt:0,fromSlot:slot,limit:120});n.terminal=false;selected=b.id;commit('Output route created and connected. Its transfer starts at 120/min; select the link to adjust it.');fit()}
function inspectSource(n){$('inspector').innerHTML=`<h2>External supply</h2><label>MATERIAL<select id="material">${opts(items,n.item)}</select></label><label>AVAILABLE / MIN<input id="supply" type="number" value="${n.supply}"></label><p>Use for fluids or production outside this plan. Connect the output to a matching machine ingredient.</p><button id="delete" class="full danger">Delete supply</button>`;$('material').onchange=ev=>{remember();n.item=ev.target.value;state.edges=state.edges.filter(e=>e.from!==n.id);commit()};editNumber('supply',v=>n.supply=v);$('delete').onclick=removeNode}
function inspectEdge(){let e=state.edges[selectedEdge];if(!e){selectedEdge=null;inspect();return}let a=get(e.from),b=get(e.to);$('inspector').innerHTML=`<div class="eyebrow">${e.kind==='route'?'CONTINUOUS BELT ROUTE':fluids.has(e.item)?'PIPE CONNECTION':'MATERIAL TRANSFER'}</div><h2>${esc(label(e.item))}</h2>${materialBadge(e.item)}<p>${esc(a.name||a.id)} → ${esc(b.name||b.id)}</p><div class="explain"><strong>${fmt(result.rates[selectedEdge])}/min</strong><br>${e.kind==='route'?'This connection carries the belt lanes continuously.':fluids.has(e.item)?'Pipe connection: fluid flows directly between fluid ports. No inserter or belt is needed.':a.kind==='machine'&&b.kind==='machine'?'Direct insertion between machines. No belt is used.':a.kind==='belt'?'Picked up from the belt by an inserter.':'Loaded onto the receiving belt by an inserter.'}</div>${e.kind==='transfer'?`<label>${fluids.has(e.item)?'PLANNED FLUID LIMIT / MIN':'PLANNED TRANSFER LIMIT / MIN'}<input id="limit" type="number" min="0" max="100000" value="${e.limit}"></label><p>${fluids.has(e.item)?'This is a planning limit, not a physical pipe simulation. Pipe distance, pumps and fluid-port placement are not modeled.':'Set transfer capacity with the inserter planner below.'}</p>${[[a,'fromSlot'],[b,'toSlot']].filter(([n])=>n.kind==='machine'&&!fluids.has(e.item)).map(([n,key])=>`<label>${n.id.toUpperCase()} LOGICAL CONNECTION<select id="${key}">${Array.from({length:100},(_,i)=>`<option value="${i}" ${e[key]===i?'selected':''}>Connection ${i+1}</option>`).join('')}</select></label>`).join('')}`:'<p>Use the route’s belt type to change its capacity. Removing this connection disconnects both lanes.</p>'}<button id="focusFrom" class="full">Inspect source</button><button id="focusTo" class="full">Inspect destination</button><button id="removeLink" class="full danger">Remove connection</button>`;if($('limit'))$('limit').onchange=ev=>{let v=+ev.target.value;if(!Number.isFinite(v)||v<0||v>100000)return;remember();e.limit=v;delete e.transport;save();result=solveFlow(state,RECIPES);render()};for(const key of ['fromSlot','toSlot'])if($(key))$(key).onchange=ev=>{let copy={...e,[key]:+ev.target.value},err=error(copy,{...state,edges:state.edges.filter(x=>x!==e)});if(err){message(err);inspect();return}remember();Object.assign(e,copy);save();render()};$('focusFrom').onclick=()=>select(a.id);$('focusTo').onclick=()=>select(b.id);$('removeLink').onclick=()=>removeEdge(selectedEdge);transportPanel(e,a,b)}
function center(){let b=$('viewport').getBoundingClientRect();return {x:Math.max(80,Math.min(5200,snap((b.width*.35-view.x)/view.z))),y:Math.max(180,Math.min(5200,snap((b.height*.45-view.y)/view.z)))}}
function addMachine(){if(state.nodes.length>=40){message('Maximum 40 nodes.');return}remember();let p=center();while(state.nodes.some(n=>n.kind==='machine'&&Math.abs(n.x-p.x)<260&&Math.abs(n.y-p.y)<220))p.y+=240;let n=machine('iron-gear-wheel',p.x,p.y);state.nodes.push(n);selected=n.id;commit('Machine added. Choose any base-game recipe and set its count.');openDetails();fit()}
function addBelt(){if(state.nodes.length>=40)return;remember();let p=center(),n=belt('NEW SUPPLY · name this route',[p,{x:p.x+300,y:p.y},{x:p.x+600,y:p.y}]);state.nodes.push(n);selected=n.id;commit('New full supply belt. Name it for what it will feed.');openDetails();fit()}
function finishDrawing(){if(!drawing||drawing.length<2){message('Place at least two points on the grid.');return}if(state.nodes.length>=40)return;remember();let n=belt('DRAWN ROUTE · name this belt',drawing.map(p=>({...p})));state.nodes.push(n);drawing=null;selected=n.id;commit('Belt drawn. Assign its lanes and name the route.');openDetails()}
function undo(){if(!history.length)return;state=JSON.parse(history.pop());selected=state.nodes[0]?.id;drawing=null;commit('Last change undone.')}
$('viewport').onpointerdown=ev=>{if(ev.button!==0||ev.target.closest('[data-tap],[data-bend],[data-drag],[data-select],[data-edge],[data-route],.machine,.splitter,#drawingHelp,#stageOverview'))return;if(drawing){let p=point(ev);if(!drawing.length||p.x!==drawing.at(-1).x||p.y!==drawing.at(-1).y)drawing.push(p);drawNetwork();message(`${drawing.length} route points. Click Finish belt when ready.`);return}drag={pan:true,x:ev.clientX,y:ev.clientY,ox:view.x,oy:view.y}};
window.addEventListener('pointermove',ev=>{if(drag){if(drag.pan){view.x=drag.ox+ev.clientX-drag.x;view.y=drag.oy+ev.clientY-drag.y;transform()}else{let n=get(drag.id),x=Math.max(40,Math.min(6000,snap(drag.ox+(ev.clientX-drag.x)/view.z))),y=Math.max(80,Math.min(6000,snap(drag.oy+(ev.clientY-drag.y)/view.z)));if(n.kind==='belt'){if(drag.whole){const dx=Math.max(40-Math.min(...drag.original.map(p=>p.x)),Math.min(6000-Math.max(...drag.original.map(p=>p.x)),x-drag.ox)),dy=Math.max(80-Math.min(...drag.original.map(p=>p.y)),Math.min(6000-Math.max(...drag.original.map(p=>p.y)),y-drag.oy));n.points=drag.original.map(p=>({x:p.x+dx,y:p.y+dy}));}else n.points[drag.at]={x,y}}else{n.x=x;n.y=y}drawNetwork();drawCards()}}if(pending){const a=get(pending.id),p=port(a,sourceItem(a,pending.fromLane),true,pending.fromLane,pending.fromAt);$('draft')?.setAttribute('d',curve(p,point(ev)))}});
window.addEventListener('pointerup',()=>{if(drag){let changed=!drag.pan;drag=null;if(changed){save();render()}}});$('viewport').addEventListener('wheel',ev=>{ev.preventDefault();zoom(ev.deltaY<0?1.1:1/1.1)},{passive:false});window.addEventListener('keydown',ev=>{if(ev.key==='Escape'){drawing=null;pending=null;drag=null;render();message('Drawing or connection cancelled.')}if(document.activeElement.isContentEditable||document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if((ev.ctrlKey||ev.metaKey)&&ev.key==='z'){ev.preventDefault();undo()}if(ev.key==='Delete'||ev.key==='Backspace'){ev.preventDefault();if(selectedEdge!==null)removeEdge(selectedEdge);else if(selected)removeNode()}});
$('moveTool').onclick=()=>{drawing=null;pending=null;render();message('Move a machine by its header or a belt by its name. Drag empty space to pan.')};$('draw').onclick=()=>{drawing=[];pending=null;render();message('Click the grid to place the start and bends, then Finish belt.');document.body.classList.remove('show-details')};$('finishDraw').onclick=finishDrawing;$('cancelDraw').onclick=()=>{drawing=null;render()};$('addSupply').onclick=()=>{if(state.nodes.length>=40)return;remember();let p=center(),n={id:id(),kind:'source',item:'water',supply:1200,...p};state.nodes.push(n);selected=n.id;commit('External supply added. Choose the material and available rate.');openDetails();fit()};$('addBelt').onclick=addBelt;$('addMachine').onclick=addMachine;$('split').onclick=()=>splitRoute(get(selected));$('showRates').onclick=()=>{const active=$('showRates').getAttribute('aria-pressed')!=='true';$('showRates').setAttribute('aria-pressed',String(active));$('showRates').textContent=active?'Hide rates':'Show rates';$('viewport').classList.toggle('show-all-rates',active)};$('focus').onclick=()=>{const edge=selectedEdge!==null?state.edges[selectedEdge]:null,nodes=edge?[get(edge.from),get(edge.to)]:[get(selected)].filter(Boolean);if(!nodes.length){message('Select a machine, belt or connection, then Focus selection.');return}const boxes=nodes.map(bounds),left=Math.min(...boxes.map(r=>r.x)),top=Math.min(...boxes.map(r=>r.y)),right=Math.max(...boxes.map(r=>r.x+r.w)),bottom=Math.max(...boxes.map(r=>r.y+r.h)),b=$('viewport').getBoundingClientRect();view.z=Math.max(.12,Math.min(1.2,(b.width-100)/(right-left),(b.height-100)/(bottom-top)));view.x=b.width/2-(left+right)/2*view.z;view.y=b.height/2-(top+bottom)/2*view.z;transform();message(edge?'Showing both ends of this connection.':'Selection centered. Drag its header or name to rearrange it.')};$('fit').onclick=fit;$('zoomIn').onclick=()=>zoom(1.25);$('zoomOut').onclick=()=>zoom(.8);$('undo').onclick=undo;$('save').onclick=()=>{save();message('Saved on this device. Export a portable copy to keep it elsewhere.')};$('selectNode').onchange=ev=>select(ev.target.value);$('pause').onclick=()=>{paused=!paused;document.body.classList.toggle('paused',paused);$('pause').textContent=paused?'▶ Resume motion':'Ⅱ Pause motion';drawNetwork()};$('details').onclick=()=>{if(matchMedia('(max-width:750px)').matches)document.body.classList.toggle('show-details');else document.body.classList.toggle('hide-details')};$('closeDetails').onclick=()=>document.body.classList.remove('show-details');$('fastDemo').onclick=()=>{remember();state=fastInserterState();selected=state.nodes.find(n=>n.recipe==='fast-inserter').id;commit('Fast inserter production plan: 60/min from 480 iron plates + 270 copper plates/min. Transfer limits are group totals; placement is schematic.');fit()};$('demo').onclick=()=>{remember();state=demoState();selected=state.nodes[1].id;commit('Follow the iron bus into its splitter: the top branch makes gears; the lower branch makes transport belts.');fit()};$('new').onclick=()=>{remember();state={version:4,nodes:[],edges:[],product:'transport-belt',rate:60,mode:'analyze'};selected=null;commit('Empty layout. Draw your supply belt or add a route.')};
$('export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='factory-flow-routes.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('import').onclick=()=>$('file').click();$('file').onchange=async ev=>{let f=ev.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();let s=migrate(JSON.parse(await f.text()));if(!validate(s))throw Error();remember();state=s;serial=Math.max(serial,...s.nodes.map(n=>+n.id.slice(1)+1));selected=s.nodes[0]?.id;commit('Layout imported.');fit()}catch{message('Import needs a valid v3 Belt Lab or v4 Route Workshop plan. Your layout is unchanged.')}ev.target.value=''};
render();requestAnimationFrame(()=>{fit();if($('viewport').getBoundingClientRect().width<700){const n=state.nodes.find(n=>n.kind==='belt');if(n){view.z=.65;view.x=35-n.points[0].x*view.z;view.y=180-n.points[0].y*view.z;transform();message('Drag the canvas to follow the branches. Fit routes shows the complete layout.')}}});

document.querySelectorAll(".file-menu button,.examples-menu button").forEach(button=>button.addEventListener("click",()=>{let menu=button.closest("details");while(menu){menu.open=false;menu=menu.parentElement?.closest("details")}}));

function machineBeltBudget(n){const rate=E.per(n)*n.count,r=RECIPES[n.recipe],tier=state.planSettings?.beltTier||'yellow',budget=planBelts(Object.fromEntries(Object.entries(E.inputs(n)).map(([item,q])=>[item,rate*q/r.out])),fluids,tier);return `<details class="machine-belts"><summary>Input belts at full machine speed</summary><p>${label(tier)} belts · both lanes assigned to one material. This is this group’s maximum demand, not the whole factory’s target.</p>${budget.map(b=>`<div class="connection"><b>${esc(label(b.item))}</b><div class="row"><span>${fmt(b.rate)}/min</span><b>${b.belts} belt${b.belts===1?'':'s'}</b></div><small>${b.lanes} lane${b.lanes===1?'':'s'} · ${fmt(b.load*100)}% of allocated capacity</small></div>`).join('')||'<p>No solid inputs. Use pipes for fluids.</p>'}</details>`}

// Refit only a view the user has left fitted; manual navigation always wins.
function refitOnCanvasResize(){if(fittedView&&['x','y','z'].every(k=>Math.abs(view[k]-fittedView[k])<1e-8))fit()}
if(typeof ResizeObserver!=='undefined'){const canvasSizeObserver=new ResizeObserver(()=>refitOnCanvasResize());canvasSizeObserver.observe($('viewport'))}
